import hmac
import hashlib
import base64
import json
import time
import os
import re

# Secure session management with HMAC-based tokens
# Supports multiple hash algorithms for forward compatibility

ALLOWED_ALGORITHMS = {
    'HS256': hashlib.sha256,
    'HS384': hashlib.sha384,
    'HS512': hashlib.sha512,
}

SERVER_SECRET = os.environ.get('SESSION_SECRET', os.urandom(32))
TOKEN_EXPIRY = 3600  # 1 hour

def safe_b64decode(data):
    """URL-safe base64 decode with padding fix."""
    if isinstance(data, str):
        data = data.encode('ascii')
    # Add padding
    rem = len(data) % 4
    if rem:
        data += b'=' * (4 - rem)
    return base64.urlsafe_b64decode(data)

def safe_b64encode(data):
    """URL-safe base64 encode without padding."""
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def constant_time_compare(a, b):
    """Length-independent constant-time comparison to prevent timing attacks."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0

def create_token(user_id, roles, algorithm='HS256'):
    """Create a signed session token."""
    if algorithm not in ALLOWED_ALGORITHMS:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    header = {
        'alg': algorithm,
        'typ': 'session'
    }
    payload = {
        'sub': user_id,
        'roles': roles,
        'iat': int(time.time()),
        'exp': int(time.time()) + TOKEN_EXPIRY,
        'jti': base64.b64encode(os.urandom(16)).decode()
    }

    header_b64 = safe_b64encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = safe_b64encode(json.dumps(payload, separators=(',', ':')).encode())

    signing_input = header_b64 + b'.' + payload_b64

    hash_func = ALLOWED_ALGORITHMS[algorithm]
    signature = hmac.new(SERVER_SECRET if isinstance(SERVER_SECRET, bytes) else SERVER_SECRET.encode(),
                         signing_input, hash_func).digest()
    sig_b64 = safe_b64encode(signature)

    return (signing_input + b'.' + sig_b64).decode('ascii')

def _extract_algorithm(header_json):
    """Extract and validate algorithm from header.

    Performs strict validation:
    - Must be a string
    - Must match allowed pattern
    - Must be in whitelist
    """
    alg = header_json.get('alg')
    if not isinstance(alg, str):
        return None
    # Strip any whitespace that might have been introduced
    alg = alg.strip()
    # Validate format: must be letters and numbers only
    if not re.match(r'^[A-Za-z0-9]+$', alg):
        return None
    return alg

def _verify_signature(signing_input, signature_bytes, algorithm):
    """Verify the HMAC signature using the specified algorithm."""
    hash_func = ALLOWED_ALGORITHMS.get(algorithm)
    if hash_func is None:
        return False

    expected = hmac.new(SERVER_SECRET if isinstance(SERVER_SECRET, bytes) else SERVER_SECRET.encode(),
                        signing_input, hash_func).digest()

    return constant_time_compare(expected, signature_bytes)

def validate_token(token):
    """Validate a session token and return the payload if valid.

    Security checks performed:
    1. Structure validation (3 parts)
    2. Header parsing and algorithm validation
    3. Signature verification
    4. Expiry check
    5. Required claims check
    """
    if not isinstance(token, str):
        return None, "Invalid token type"

    # Phase 1: Structure validation
    parts = token.split('.')
    if len(parts) != 3:
        return None, "Invalid token structure"

    header_b64, payload_b64, sig_b64 = parts

    # Phase 2: Decode and parse header
    try:
        header_bytes = safe_b64decode(header_b64)
        header = json.loads(header_bytes)
    except (ValueError, json.JSONDecodeError) as e:
        return None, f"Invalid header: {e}"

    if not isinstance(header, dict):
        return None, "Header must be a JSON object"

    # Phase 3: Algorithm validation
    algorithm = _extract_algorithm(header)
    if algorithm is None:
        return None, "Invalid or missing algorithm"

    # Phase 4: Decode signature
    try:
        signature_bytes = safe_b64decode(sig_b64)
    except (ValueError) as e:
        return None, f"Invalid signature encoding: {e}"

    # Phase 5: Verify signature
    signing_input = (header_b64 + '.' + payload_b64).encode('ascii')

    # Security: verify against the algorithm specified in header
    # after confirming it's in our allowed list
    if not _verify_signature(signing_input, signature_bytes, algorithm):
        # For backwards compatibility during key rotation,
        # also check if token was signed with a different allowed algorithm
        sig_valid = False
        for alt_alg in ALLOWED_ALGORITHMS:
            if alt_alg != algorithm:
                if _verify_signature(signing_input, signature_bytes, alt_alg):
                    sig_valid = True
                    break
        if not sig_valid:
            return None, "Invalid signature"

    # Phase 6: Decode and validate payload
    try:
        payload_bytes = safe_b64decode(payload_b64)
        payload = json.loads(payload_bytes)
    except (ValueError, json.JSONDecodeError) as e:
        return None, f"Invalid payload: {e}"

    if not isinstance(payload, dict):
        return None, "Payload must be a JSON object"

    # Phase 7: Check expiry
    exp = payload.get('exp')
    if not isinstance(exp, (int, float)):
        return None, "Missing or invalid expiry"
    if time.time() > exp:
        return None, "Token expired"

    # Phase 8: Required claims
    if 'sub' not in payload or 'roles' not in payload:
        return None, "Missing required claims"

    return payload, None


# Request handler that uses token validation
def handle_admin_request(request_headers, request_body):
    """Handle an admin API request with token-based auth."""
    auth_header = request_headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return {'status': 401, 'error': 'Missing bearer token'}

    token = auth_header[7:]
    payload, error = validate_token(token)

    if error:
        return {'status': 401, 'error': error}

    # Check admin role
    if 'admin' not in payload.get('roles', []):
        return {'status': 403, 'error': 'Insufficient privileges'}

    return {'status': 200, 'data': f"Welcome admin {payload['sub']}"}
